import test from 'node:test';
import assert from 'node:assert/strict';
import { PIECE_COUNT, PuzzleState, fitScale, shuffledOrder, sliceBounds } from '../src/games/puzzle/puzzleLogic.js';

const inventory = state => [...state.tray, ...state.board].filter(piece => piece !== null).sort((a, b) => a - b);
const all = Array.from({ length: PIECE_COUNT }, (_, i) => i);

test('slices cover the whole image in 15 unique, non-overlapping pieces', () => {
  for (const [w, h] of [[400, 400], [800, 300], [300, 800], [1001, 667]]) {
    const pieces = sliceBounds(w, h);
    assert.equal(pieces.length, 15);
    assert.equal(new Set(pieces.map(p => `${p.x},${p.y}`)).size, 15);
    assert.equal(pieces.reduce((sum, p) => sum + p.w * p.h, 0), w * h);
    assert.ok(pieces.every(p => p.w > 0 && p.h > 0 && p.x + p.w <= w && p.y + p.h <= h));
  }
  assert.throws(() => sliceBounds(0, 10));
});

test('fit keeps the aspect ratio inside the box', () => {
  assert.equal(fitScale(800, 300, 400, 400), 0.5);
  assert.equal(fitScale(300, 800, 400, 400), 0.5);
});

test('shuffle is a permutation and never the solved order', () => {
  for (let i = 0; i < 50; i++) assert.deepEqual([...shuffledOrder()].sort((a, b) => a - b), all);
  let calls = 0;
  const identityFirst = () => (calls++ < PIECE_COUNT - 1 ? 0.999 : 0);
  assert.notDeepEqual(shuffledOrder(PIECE_COUNT, identityFirst), all);
});

test('placements count attempts and correct pieces stay fixed', () => {
  const state = new PuzzleState([...all].reverse());
  state.tapTray(0); // piece 14
  assert.equal(state.selected, 14);
  assert.equal(state.tapBoard(0).correct, false);
  assert.deepEqual([state.attempts, state.correct], [1, 0]);
  state.tapBoard(0); // reselect the wrong piece on the board
  assert.equal(state.tapBoard(14).correct, true);
  assert.deepEqual([state.attempts, state.correct], [2, 1]);
  assert.equal(state.tapBoard(14), null, 'a fixed piece cannot be selected again');
  assert.equal(state.tapBoard(14), null);
  assert.deepEqual([state.attempts, state.correct], [2, 1]);
  assert.deepEqual(inventory(state), all);
});

test('placing on a wrong piece sends it back to the tray without duplicates', () => {
  const state = new PuzzleState([...all].reverse());
  state.tapTray(0); state.tapBoard(3); // piece 14 on cell 3
  state.tapTray(1); const result = state.tapBoard(3); // piece 13 replaces it
  assert.deepEqual(result.moved, [13, 14]);
  assert.equal(state.tray[1], 14);
  state.tapBoard(3); const move = state.tapBoard(5); // board piece to another empty cell
  assert.equal(state.board[3], null);
  assert.equal(state.board[5], 13);
  assert.equal(move.type, 'place');
  state.tapBoard(5); state.tapTray(0); // empty tray slot takes it back, no attempt
  assert.equal(state.tray[0], 13);
  assert.equal(state.attempts, 3);
  assert.deepEqual(inventory(state), all);
});

test('repeated taps do not duplicate pieces or attempts', () => {
  const state = new PuzzleState([...all].reverse());
  state.tapTray(0);
  state.tapTray(0);
  assert.equal(state.selected, null);
  state.tapTray(0); state.tapBoard(2); state.tapBoard(2);
  assert.equal(state.selected, 14);
  state.tapBoard(2);
  assert.equal(state.selected, null);
  assert.equal(state.attempts, 1);
  assert.deepEqual(inventory(state), all);
});

test('complete only when every cell holds its own piece, then ignores input', () => {
  const state = new PuzzleState([...all].reverse());
  let last;
  for (let piece = 0; piece < PIECE_COUNT; piece++) {
    assert.equal(state.complete, false);
    state.tapTray(state.tray.indexOf(piece));
    last = state.tapBoard(piece);
  }
  assert.equal(last.complete, true);
  assert.deepEqual([state.attempts, state.correct], [15, 15]);
  assert.equal(state.tapTray(0), null);
  assert.equal(state.tapBoard(0), null);
});

