  constructor(trayOrder = shuffledOrder()) {
    if (trayOrder.length !== PIECE_COUNT || new Set(trayOrder).size !== PIECE_COUNT) throw new Error('Ordem de peças inválida.');
    this.tray = [...trayOrder];
    this.board = Array(PIECE_COUNT).fill(null);
    this.selected = null;
    this.attempts = 0;
    this.correct = 0;
  }
  locate(piece) {
    const cell = this.board.indexOf(piece);
    return cell >= 0 ? { area: 'board', index: cell } : { area: 'tray', index: this.tray.indexOf(piece) };
  }
  isLocked(piece) { return this.board[piece] === piece; }
  get complete() { return this.board.every((piece, cell) => piece === cell); }
  tapTray(slot) {
    if (this.complete) return null;
    const piece = this.tray[slot];
    if (piece !== null) {
      this.selected = this.selected === piece ? null : piece;
      return { type: 'select' };
    }
    if (this.selected === null) return null;
    const moved = this.selected;
    this.board[this.locate(moved).index] = null;
    this.tray[slot] = moved;
    this.selected = null;
    return { type: 'return', moved: [moved] };
  }
  tapBoard(cell) {
    if (this.complete) return null;
    const occupant = this.board[cell];
    if (this.selected === null) {
      if (occupant === null || this.isLocked(occupant)) return null;
      this.selected = occupant;
      return { type: 'select' };
    }
    if (occupant === this.selected) { this.selected = null; return { type: 'select' }; }
    if (occupant !== null && this.isLocked(occupant)) return null;
    const piece = this.selected, from = this.locate(piece);
    if (from.area === 'tray') this.tray[from.index] = null;
    else this.board[from.index] = null;
    const moved = [piece];
    if (occupant !== null) {
      const slot = from.area === 'tray' ? from.index : this.tray.indexOf(null);
      this.tray[slot] = occupant;
      moved.push(occupant);
    }
    this.board[cell] = piece;
    this.selected = null;
    this.attempts++;
    const correct = piece === cell;
    if (correct) this.correct++;
    return { type: 'place', moved, correct, complete: this.complete };
  }
}

