import { BaseGameScene } from '../../core/BaseGameScene.js';
import { COLS, PIECE_COUNT, PuzzleState, fitScale, sliceBounds } from './puzzleLogic.js';

// Layout in the 960 x 600 logical space: reference on top, tray (left) and board (right) side by side.
const INK = '#183b39';
const COLORS = { line: 0x9fbcb1, cell: 0xffffff, tray: 0xe3eee8, select: 0xa85c16 };
const REFERENCE = { x: 20, y: 44, w: 200, h: 96 };
const AREA = { y: 180, w: 440, h: 404, trayX: 20, boardX: 500 };
const GAP = 8;

export class PuzzleScene extends BaseGameScene {
  buildBoard() {
    const image = this.activity.images[0];
    const texture = this.textures.get(image.id);
    const source = texture.getSourceImage();
    const bounds = sliceBounds(source.width, source.height);
    const scale = fitScale(source.width, source.height, AREA.w - GAP * (COLS - 1), AREA.h - GAP * 2);
    const boardW = source.width * scale, boardH = source.height * scale;
    const boardX = AREA.boardX + (AREA.w - boardW) / 2, trayX = AREA.trayX + (AREA.w - boardW - GAP * (COLS - 1)) / 2;
    const top = AREA.y + (AREA.h - boardH - GAP * 2) / 2;
    const rect = (x0, gap, b) => ({ x: x0 + b.x * scale + b.col * gap, y: top + b.y * scale + b.row * gap, w: b.w * scale, h: b.h * scale });
    this.cells = { board: bounds.map(b => rect(boardX, 0, b)), tray: bounds.map(b => rect(trayX, GAP, b)) };
    this.state = new PuzzleState();
    this.selection = null;

    const ref = this.add.image(REFERENCE.x, REFERENCE.y, image.id).setOrigin(0);
    ref.setScale(fitScale(source.width, source.height, REFERENCE.w, REFERENCE.h));
    this.add.text(REFERENCE.x, 14, 'Modelo', { fontSize: '18px', color: INK, fontStyle: 'bold' });
    this.add.text(250, 44, 'Toque em uma peça e depois no lugar dela no quadro.', { fontSize: '24px', color: INK, wordWrap: { width: 690 } });
    this.feedback = this.add.text(250, 96, '', { fontSize: '22px', color: INK, wordWrap: { width: 690 } });
    this.add.text(AREA.trayX + AREA.w / 2, AREA.y - 26, 'Peças', { fontSize: '18px', color: INK, fontStyle: 'bold' }).setOrigin(0.5, 0);
    this.add.text(AREA.boardX + AREA.w / 2, AREA.y - 26, 'Quadro', { fontSize: '18px', color: INK, fontStyle: 'bold' }).setOrigin(0.5, 0);

    const grid = this.add.graphics();
    for (const [area, fill] of [['tray', COLORS.tray], ['board', COLORS.cell]]) for (const c of this.cells[area]) {
      grid.fillStyle(fill).fillRect(c.x, c.y, c.w, c.h).lineStyle(2, COLORS.line).strokeRect(c.x, c.y, c.w, c.h);
    }
    this.highlight = this.add.graphics().setDepth(3);

    this.pieces = bounds.map(b => {
      const frame = `puzzle-piece-${b.index}`;
      if (!texture.has(frame)) texture.add(frame, 0, b.x, b.y, b.w, b.h);
      return this.add.image(0, 0, image.id, frame).setScale(scale).setDepth(1);
    });
    for (const area of ['tray', 'board']) this.cells[area].forEach((c, index) => {
      this.add.zone(c.x, c.y, c.w, c.h).setOrigin(0).setInteractive({ useHandCursor: true })
        .on('pointerdown', () => this.handleTap(area, index));
    });
    this.pieces.forEach((_, piece) => this.movePiece(piece, false));
    this.updateFeedback('');
  }
  handleTap(area, index) {
    if (this.finished) return;
    const result = area === 'tray' ? this.state.tapTray(index) : this.state.tapBoard(index);
    if (!result) return;
    for (const piece of result.moved ?? []) this.movePiece(piece, true);
    this.drawSelection();
    if (result.type !== 'place') return this.updateFeedback(this.state.selected === null ? '' : 'Agora toque no lugar dessa peça no quadro.');
    this.metrics.attempts = this.state.attempts;
    this.metrics.correct = this.state.correct;
    if (result.complete) {
      this.updateFeedback('Parabéns! Você montou o quebra-cabeça.');
      this.finish('completed');
    } else this.updateFeedback(result.correct ? 'Encaixou!' : 'Ainda não é esse lugar. Você pode trocar a peça.');
  }
  movePiece(piece, animate) {
    const { area, index } = this.state.locate(piece);
    const c = this.cells[area][index];
    const sprite = this.pieces[piece];
    const x = c.x + c.w / 2, y = c.y + c.h / 2;
    this.tweens.killTweensOf(sprite);
    if (!animate || this.activity.settings?.reducedMotion) return sprite.setPosition(x, y).setDepth(1);
    sprite.setDepth(2);
    this.tweens.add({ targets: sprite, x, y, duration: 180, ease: 'Cubic.easeOut', onComplete: () => sprite.setDepth(1) });
  }
  drawSelection() {
    this.highlight.clear();
    if (this.state.selected === null) return;
    const { area, index } = this.state.locate(this.state.selected);
    const c = this.cells[area][index];
    this.highlight.lineStyle(5, COLORS.select).strokeRect(c.x - 2, c.y - 2, c.w + 4, c.h + 4);
  }
  updateFeedback(message) {
    const placed = this.state.board.filter((piece, cell) => piece === cell).length;
    this.feedback.setText(`${message ? `${message} ` : ''}Peças no lugar: ${placed} de ${PIECE_COUNT}.`);
  }
}

