  const shots = 'C:/Users/migue/AppData/Local/Temp/claude/C--Users-migue-Documents-hackathon-dopamine/deb0fe64-a730-42b2-ab28-2a5a24f8783a/scratchpad/';
  const svg = (w, h) => `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">` + Array.from({ length: 15 }, (_, i) => { const c = i % 5, r = Math.floor(i / 5); return `<rect x="${c * w / 5}" y="${r * h / 3}" width="${w / 5}" height="${h / 3}" fill="hsl(${i * 24},60%,${55 + (i % 2) * 15}%)"/><text x="${(c + .5) * w / 5}" y="${(r + .5) * h / 3}" font-size="${Math.min(w / 5, h / 3) / 2}" text-anchor="middle" dominant-baseline="middle" font-family="sans-serif">${i + 1}</text>`; }).join('') + '</svg>';
  async function run(opts) {
    const ctx = await page.context().browser().newContext({ viewport: opts.viewport, hasTouch: !!opts.touch, isMobile: !!opts.touch });
    const p = await ctx.newPage();
    const results = [], errors = [];
    p.on('pageerror', e => errors.push(String(e)));
    p.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.text()); });
    await p.exposeFunction('__rec', r => results.push(r));
    await p.addInitScript(() => { Math.random = () => 0; window.addEventListener('activity-result', e => window.__rec(e.detail)); });
    if (opts.size) await p.route('**/assets/demo/dino-1.svg', r => r.fulfill({ contentType: 'image/svg+xml', body: svg(...opts.size) }));
    await p.goto('http://127.0.0.1:5174/');
    await p.addScriptTag({ type: 'module', content: `import * as L from '/src/games/puzzle/puzzleLogic.js'; window.__L = L;` });
    await p.waitForFunction(() => window.__L);
    const start = async () => { await p.getByRole('button', { name: 'Quebra-cabeça' }).click(); await p.waitForTimeout(1200); };
    await start();
    const [W, H] = opts.size ?? [400, 400];
    const geo = await p.evaluate(([W, H]) => {
      const L = window.__L, GAP = 8, A = { y: 180, w: 440, h: 404, trayX: 20, boardX: 500 };
      const b = L.sliceBounds(W, H), s = L.fitScale(W, H, A.w - GAP * 4, A.h - GAP * 2);
      const bw = W * s, bh = H * s, boardX = A.boardX + (A.w - bw) / 2, trayX = A.trayX + (A.w - bw - GAP * 4) / 2, top = A.y + (A.h - bh - GAP * 2) / 2;
      const c = (x0, g, q) => [x0 + q.x * s + q.col * g + q.w * s / 2, top + q.y * s + q.row * g + q.h * s / 2];
      const r = document.querySelector('canvas').getBoundingClientRect();
      window.__S = new L.PuzzleState(L.shuffledOrder(15, () => 0));
      return { tray: b.map(q => c(trayX, GAP, q)), board: b.map(q => c(boardX, 0, q)), rect: { x: r.x, y: r.y, k: r.width / 960 }, cellPx: [b[0].w * s * r.width / 960, b[0].h * s * r.width / 960] };
    }, [W, H]);
    const tap = async (area, i) => {
      const [x, y] = geo[area][i], cx = geo.rect.x + x * geo.rect.k, cy = geo.rect.y + y * geo.rect.k;
      if (opts.touch) await p.touchscreen.tap(cx, cy); else await p.mouse.click(cx, cy);
      await p.evaluate(([a, i]) => a === 'tray' ? window.__S.tapTray(i) : window.__S.tapBoard(i), [area, i]);
    };
    const where = piece => p.evaluate(x => window.__S.locate(x), piece);
    const order = await p.evaluate(() => [...window.__S.tray]);
    // 1) wrong placement, 2) rapid repeated taps on a correct one, 3) correct the wrong one, 4) rest
    const a = order[0], wrong = (a + 1) % 15;
    await tap('tray', 0); await tap('board', wrong);
    const b = order[1];
    await tap('tray', 1); await Promise.all([tap('board', b)]); await tap('board', b); await tap('board', b);
    await p.screenshot({ path: shots + opts.name + '-meio.png' });
    const mid = await p.evaluate(() => [window.__S.attempts, window.__S.correct]);
    await tap('board', wrong); await tap('board', a);
    for (let piece = 0; piece < 15; piece++) {
      const loc = await where(piece);
      if (loc.area === 'board' && loc.index === piece) continue;
      await tap(loc.area, loc.index); await tap('board', piece);
    }
    await p.waitForTimeout(400);
    await p.screenshot({ path: shots + opts.name + '-fim.png' });
    await tap('board', 0); await tap('tray', 0);
    const afterDone = results.length;
    await p.getByRole('button', { name: 'Voltar ao menu' }).click();
    const afterExit = results.length;
    await start();
    await p.screenshot({ path: shots + opts.name + '-nova.png' });
    await p.getByRole('button', { name: 'Voltar ao menu' }).click();
    await ctx.close();
    return { name: opts.name, cellPx: geo.cellPx.map(Math.round), mid, afterDone, afterExit, results, errors };
  }
  const out = [];
  out.push(await run({ name: 'quadrada-mouse', viewport: { width: 1100, height: 900 } }));
  out.push(await run({ name: 'larga-mouse', viewport: { width: 1100, height: 900 }, size: [800, 300] }));
  out.push(await run({ name: 'alta-toque', viewport: { width: 740, height: 390 }, size: [300, 800], touch: true }));
  return JSON.stringify(out, null, 1);
})(page);
