await (async (page) => {
  const shots = 'C:/Users/migue/AppData/Local/Temp/claude/C--Users-migue-Documents-hackathon-dopamine/deb0fe64-a730-42b2-ab28-2a5a24f8783a/scratchpad/';
  const svg = (w, h) => `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">` + Array.from({ length: 15 }, (_, i) => { const c = i % 5, r = Math.floor(i / 5); return `<rect x="${c * w / 5}" y="${r * h / 3}" width="${w / 5}" height="${h / 3}" fill="hsl(${i * 24},70%,${45 + (i % 3) * 15}%)"/><text x="${(c + .5) * w / 5}" y="${(r + .5) * h / 3}" font-size="${Math.min(w / 5, h / 3) / 2}" text-anchor="middle" dominant-baseline="middle" font-family="sans-serif">${i + 1}</text>`; }).join('') + '</svg>';
  async function run(opts) {
    const ctx = await page.context().browser().newContext({ viewport: opts.viewport, hasTouch: !!opts.touch, isMobile: !!opts.touch, deviceScaleFactor: 1 });
    const p = await ctx.newPage();
    const results = [], errors = [];
    p.on('pageerror', e => errors.push(String(e)));
    p.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.text()); });
    await p.exposeFunction('__rec', r => results.push(r));
    await p.addInitScript(() => window.addEventListener('activity-result', e => window.__rec(e.detail)));
    const [W, H] = opts.size;
    const body = svg(W, H);
    await p.route('**/assets/demo/dino-1.svg', r => r.fulfill({ contentType: 'image/svg+xml', body }));
    await p.goto('http://127.0.0.1:5174/');
    await p.addScriptTag({ type: 'module', content: `import * as L from '/src/games/puzzle/puzzleLogic.js'; window.__L = L;` });
    await p.waitForFunction(() => window.__L);
    const start = async () => { await p.getByRole('button', { name: 'Quebra-cabeça' }).click(); await p.waitForTimeout(1200); };
    const geoFn = async () => p.evaluate(([W, H]) => {
      const L = window.__L, GAP = 8, A = { y: 180, w: 440, h: 404, trayX: 20, boardX: 500 };
      const b = L.sliceBounds(W, H), s = L.fitScale(W, H, A.w - GAP * 4, A.h - GAP * 2);
      const bw = W * s, bh = H * s, boardX = A.boardX + (A.w - bw) / 2, trayX = A.trayX + (A.w - bw - GAP * 4) / 2, top = A.y + (A.h - bh - GAP * 2) / 2;
      const r = document.querySelector('canvas').getBoundingClientRect(), k = r.width / 960;
      const c = (x0, g, q, f) => [r.x + k * (x0 + q.x * s + q.col * g + q.w * s * f), r.y + k * (top + q.y * s + q.row * g + q.h * s * f)];
      return { tray: b.map(q => c(trayX, GAP, q, .5)), board: b.map(q => c(boardX, 0, q, .5)), traySample: b.map(q => c(trayX, GAP, q, .15)), boardSample: b.map(q => c(boardX, 0, q, .15)), cellPx: [Math.round(b[0].w * s * k), Math.round(b[0].h * s * k)] };
    }, [W, H]);
    // Read which piece sits in each slot by comparing screenshot pixels with the source colours.
    const readSlots = async (key) => {
      const png = (await p.screenshot()).toString('base64');
      return p.evaluate(async ([png, body, W, H, pts]) => {
        const load = src => new Promise(ok => { const i = new Image(); i.onload = () => ok(i); i.src = src; });
        const draw = (img, w, h) => { const c = document.createElement('canvas'); c.width = w; c.height = h; const x = c.getContext('2d'); x.drawImage(img, 0, 0); return x; };
        const shot = await load('data:image/png;base64,' + png), sx = draw(shot, shot.width, shot.height);
        const src = draw(await load('data:image/svg+xml;base64,' + btoa(body)), W, H);
        const ref = window.__L.sliceBounds(W, H).map(q => src.getImageData(Math.floor(q.x + q.w * .15), Math.floor(q.y + q.h * .15), 1, 1).data);
        return pts.map(([x, y]) => { const d = sx.getImageData(Math.round(x), Math.round(y), 1, 1).data; let best = null, bd = 60; ref.forEach((r, i) => { const dist = Math.abs(r[0] - d[0]) + Math.abs(r[1] - d[1]) + Math.abs(r[2] - d[2]); if (dist < bd) { bd = dist; best = i; } }); return best; });
      }, [png, body, W, H, geo[key]]);
    };
    await start();
    let geo = await geoFn();
    const order = await readSlots('traySample');
    await p.evaluate(o => { window.__S = new window.__L.PuzzleState(o); }, order);
    const tap = async (area, i) => {
      const [x, y] = geo[area][i];
      if (opts.touch) await p.touchscreen.tap(x, y); else await p.mouse.click(x, y);
      await p.evaluate(([a, i]) => a === 'tray' ? window.__S.tapTray(i) : window.__S.tapBoard(i), [area, i]);
    };
    const where = piece => p.evaluate(x => window.__S.locate(x), piece);
    const a = order[0], wrong = (a + 1) % 15, b = order[1];
    await tap('tray', 0); await tap('board', wrong);           // wrong placement
    await tap('tray', 1); await tap('board', b);               // correct placement
    await tap('board', b); await tap('board', b);              // repeated taps on a fixed piece
    // fast double click directly on the canvas: select a tray piece and place twice
    await tap('tray', 2); 
    const c = order[2], [cx, cy] = geo.board[(c + 2) % 15 === wrong ? (c + 3) % 15 : (c + 2) % 15];
    const target = (c + 2) % 15 === wrong ? (c + 3) % 15 : (c + 2) % 15;
    if (opts.touch) { await p.touchscreen.tap(cx, cy); await p.touchscreen.tap(cx, cy); } else await p.mouse.dblclick(cx, cy);
    await p.evaluate(t => { window.__S.tapBoard(t); window.__S.tapBoard(t); }, target);
    await p.waitForTimeout(300);
    await p.screenshot({ path: shots + opts.name + '-meio.png' });
    const boardSeen = await readSlots('boardSample');
    const boardModel = await p.evaluate(() => window.__S.board.map(x => x));
    const traySeen = await readSlots('traySample');
    const trayModel = await p.evaluate(() => window.__S.tray.map(x => x));
    const mid = await p.evaluate(() => [window.__S.attempts, window.__S.correct]);
    for (let piece = 0; piece < 15; piece++) {
      const loc = await where(piece);
      if (loc.area === 'board' && loc.index === piece) continue;
      await tap(loc.area, loc.index); await tap('board', piece);
    }
    await p.waitForTimeout(400);
    await p.screenshot({ path: shots + opts.name + '-fim.png' });
    const finalSeen = await readSlots('boardSample');
    const model = await p.evaluate(() => [window.__S.attempts, window.__S.correct]);
    await tap('board', 0); await tap('tray', 0);
    const afterDone = results.length;
    await p.getByRole('button', { name: 'Voltar ao menu' }).click();
    const afterExit = results.length;
    await start();
    geo = await geoFn();
    const newOrder = await readSlots('traySample');
    const newBoard = await readSlots('boardSample');
    await p.screenshot({ path: shots + opts.name + '-nova.png' });
    await p.getByRole('button', { name: 'Voltar ao menu' }).click();
    await ctx.close();
    return { name: opts.name, cellPx: geo.cellPx, order, mid, model, midMatches: JSON.stringify(boardSeen) === JSON.stringify(boardModel) && JSON.stringify(traySeen) === JSON.stringify(trayModel), finalSeen, afterDone, afterExit, newOrder, newBoard, results, errors };
  }
  const out = [];
  out.push(await run({ name: 'quadrada-mouse', viewport: { width: 1100, height: 900 }, size: [400, 400] }));
  out.push(await run({ name: 'larga-mouse', viewport: { width: 1100, height: 900 }, size: [800, 300] }));
  out.push(await run({ name: 'alta-toque', viewport: { width: 740, height: 390 }, size: [300, 800], touch: true }));
  return JSON.stringify(out);
})(page);
