import { BaseGameScene } from '../../core/BaseGameScene.js';
import { COLS, PIECE_COUNT, PuzzleState, fitScale, sliceBounds } from './puzzleLogic.js';

// Layout in the 960 x 600 logical space: reference on top, tray (left) and board (right) side by side.
const INK = '#183b39';
const FONT = 'system-ui, sans-serif';
const COLORS = { line: 0x9fbcb1, cell: 0xffffff, tray: 0xe3eee8, select: 0xa85c16 };
const REFERENCE = { x: 20, y: 44, w: 200, h: 96 };
const AREA = { y: 180, w: 440, h: 404, trayX: 20, boardX: 500 };
const GAP = 8;

export class PuzzleScene extends BaseGameScene {
  buildBoard() {
    const image = this.activity.images[0];
    const texture = this.textures.get(image.id);
    const source = texture.getSourceImage();
    const bounds = sliceBounds(source.width, source.height);
    const scale = fitScale(source.width, source.height, AREA.w - GAP * (COLS - 1), AREA.h - GAP * 2);
    const boardW = source.width * scale, boardH = source.height * scale;
    const boardX = AREA.boardX + (AREA.w - boardW) / 2, trayX = AREA.trayX + (AREA.w - boardW - GAP * (COLS - 1)) / 2;
    const top = AREA.y + (AREA.h - boardH - GAP * 2) / 2;
    const rect = (x0, gap, b) => ({ x: x0 + b.x * scale + b.col * gap, y: top + b.y * scale + b.row * gap, w: b.w * scale, h: b.h * scale });
    this.cells = { board: bounds.map(b => rect(boardX, 0, b)), tray: bounds.map(b => rect(trayX, GAP, b)) };
    this.state = new PuzzleState();

    const ref = this.add.image(REFERENCE.x, REFERENCE.y, image.id).setOrigin(0);
    ref.setScale(fitScale(source.width, source.height, REFERENCE.w, REFERENCE.h));
    this.add.text(REFERENCE.x, 14, 'Modelo', { fontFamily: FONT, fontSize: '18px', color: INK, fontStyle: 'bold' });
    this.add.text(250, 44, 'Toque em uma peça e depois no lugar dela no quadro.', { fontFamily: FONT, fontSize: '24px', color: INK, wordWrap: { width: 690 } });
    this.feedback = this.add.text(250, 96, '', { fontFamily: FONT, fontSize: '22px', color: INK, wordWrap: { width: 690 } });
    this.add.text(AREA.trayX + AREA.w / 2, AREA.y - 26, 'Peças', { fontFamily: FONT, fontSize: '18px', color: INK, fontStyle: 'bold' }).setOrigin(0.5, 0);
